sp_widget.css:
/* =========================================================
   GATENOW LANDING · ABOUT
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.
   Component rules are scoped as .gna-about .gna-x so nothing
   in the portal theme or Bootstrap outranks them.

   Two deliberate decisions:

   1. The section sits on white and lifts over the hero on a
      rounded seam. The hero is a pale blue wash, so sharing
      that wash made the two read as one slab.

   2. Animation is CSS only, runs on load with a stagger, and
      never holds an element at opacity zero in a base rule.
      The from-state comes from animation-fill-mode backwards,
      so if animation is blocked the content still renders.
      Scroll linked animation is avoided on purpose, since
      animation-timeline resolves against the nearest scroll
      container and this section clips its own overflow.
   ========================================================= */

/* ---------- typeface ----------
   The same face as the hero. If both widgets sit on one page,
   keep a single copy of this block, ideally in a shared Style
   Sheet record attached to the theme, and delete it here.
   ------------------------------------------------------------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- palette ---------- */
$gna-navy:      #0a2540;
$gna-blue:      #1560e0;
$gna-blue-dk:   #0f4cbb;
$gna-blue-soft: #eef3fd;
$gna-blue-tint: #dbe7fa;
$gna-body:      #55677f;
$gna-hair:      #e4eaf4;
$gna-white:     #ffffff;

$gna-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   SECTION
   The negative margin and rounded top edge lift this section
   over the hero, which is what separates them.
   ========================================================= */

.gna-about {
  position: relative;
  z-index: 1;
  width: 100%;
  margin-top: -52px;
  padding: 116px 24px 128px;
  border-radius: 52px 52px 0 0;
  font-family: $gna-font;
  color: $gna-navy;
  background: $gna-white;
  box-shadow: 0 -24px 60px rgba(16, 54, 110, 0.07);
  overflow: hidden;
}

/* faint wash so the white is not flat */
.gna-about::before {
  content: "";
  position: absolute;
  top: -180px;
  right: -160px;
  width: 620px;
  height: 620px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(21, 96, 224, 0.07) 0%, rgba(21, 96, 224, 0) 68%);
  pointer-events: none;
}

.gna-about *,
.gna-about *::before,
.gna-about *::after { box-sizing: border-box; }

.gna-about__inner {
  position: relative;
  max-width: 1160px;
  margin: 0 auto;
}


/* =========================================================
   HEADER
   Left aligned against the hero's centred header, which is
   half of what makes the two sections feel distinct.
   ========================================================= */

.gna-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 430px);
  align-items: end;
  gap: 20px 64px;
}

.gna-head__lead { min-width: 0; }

.gna-head__aside { min-width: 0; }

.gna-about .gna-eyebrow {
  display: inline-flex;
  align-items: center;
  padding: 8px 18px;
  margin: 0 0 22px;
  border-radius: 999px;
  background: $gna-blue-soft;
  color: $gna-blue;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.gna-about .gna-title {
  max-width: 620px;
  margin: 0;
  font-size: 50px;
  font-weight: 700;
  line-height: 1.14;
  letter-spacing: -0.03em;
  color: $gna-navy;
}

@supports (font-size: clamp(30px, 3.9vw, 50px)) {
  .gna-about .gna-title { font-size: clamp(30px, 3.9vw, 50px); }
}

.gna-about .gna-sub {
  margin: 0;
  padding: 0 0 0 26px;
  border-left: 2px solid $gna-blue-tint;
  font-size: 17px;
  font-weight: 400;
  line-height: 1.68;
  color: $gna-body;
}


/* =========================================================
   PANELS
   Widths alternate 7 / 5 then 5 / 7 so the block has rhythm
   instead of sitting as a flat two by two.
   ========================================================= */

.gna-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 22px;
  margin-top: 74px;
}

.gna-panel--1 { grid-column: span 7; }
.gna-panel--2 { grid-column: span 5; }
.gna-panel--3 { grid-column: span 5; }
.gna-panel--4 { grid-column: span 7; }

.gna-panel {
  position: relative;
  display: block;
  padding: 40px 38px 42px;
  border: 1px solid $gna-hair;
  border-radius: 26px;
  background: $gna-white;
  overflow: hidden;
  will-change: transform;
  transition: transform 0.62s cubic-bezier(0.45, 0.05, 0.25, 1),
              box-shadow 0.62s cubic-bezier(0.45, 0.05, 0.25, 1),
              border-color 0.62s cubic-bezier(0.45, 0.05, 0.25, 1);
}

/* glow that blooms from the corner on hover */
.gna-panel::after {
  content: "";
  position: absolute;
  top: -120px;
  right: -120px;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(21, 96, 224, 0.10) 0%, rgba(21, 96, 224, 0) 70%);
  opacity: 0;
  transform: scale(0.7);
  transition: opacity 0.7s cubic-bezier(0.45, 0.05, 0.25, 1),
              transform 0.7s cubic-bezier(0.45, 0.05, 0.25, 1);
  pointer-events: none;
}

/* accent that draws across the top edge on hover */
.gna-panel__rule {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 3px;
  transform: scaleX(0);
  transform-origin: left center;
  background: linear-gradient(90deg, $gna-blue 0%, #5b93ee 100%);
  transition: transform 0.7s cubic-bezier(0.45, 0.05, 0.25, 1);
}

.gna-panel__ghost {
  position: absolute;
  top: 18px;
  right: 26px;
  font-size: 76px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
  color: rgba(21, 96, 224, 0.06);
  transition: color 0.62s cubic-bezier(0.45, 0.05, 0.25, 1),
              transform 0.62s cubic-bezier(0.45, 0.05, 0.25, 1);
  pointer-events: none;
}

.gna-panel__icon {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border-radius: 18px;
  background: $gna-blue-soft;
  color: $gna-blue;
  font-size: 20px;
  transition: transform 0.62s cubic-bezier(0.45, 0.05, 0.25, 1),
              background 0.62s cubic-bezier(0.45, 0.05, 0.25, 1),
              color 0.62s cubic-bezier(0.45, 0.05, 0.25, 1),
              box-shadow 0.62s cubic-bezier(0.45, 0.05, 0.25, 1);
}

.gna-about .gna-panel__kicker {
  position: relative;
  display: block;
  margin: 26px 0 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: $gna-blue;
}

.gna-about .gna-panel__title {
  position: relative;
  margin: 0;
  font-size: 25px;
  font-weight: 600;
  line-height: 1.26;
  letter-spacing: -0.02em;
  color: $gna-navy;
  transition: color 0.62s cubic-bezier(0.45, 0.05, 0.25, 1);
}

.gna-about .gna-panel__text {
  position: relative;
  max-width: 520px;
  margin: 14px 0 0;
  padding: 0;
  font-size: 16.5px;
  font-weight: 400;
  line-height: 1.7;
  color: $gna-body;
}


/* =========================================================
   HOVER
   ========================================================= */

.gna-panel:hover {
  transform: translateY(-4px);
  border-color: rgba(21, 96, 224, 0.22);
  box-shadow: 0 26px 60px rgba(16, 54, 110, 0.13);
}

.gna-panel:hover::after {
  opacity: 1;
  transform: scale(1);
}

.gna-panel:hover .gna-panel__rule { transform: scaleX(1); }

.gna-panel:hover .gna-panel__icon {
  transform: translateY(-2px) rotate(-6deg);
  background: $gna-blue;
  color: $gna-white;
  box-shadow: 0 14px 28px rgba(21, 96, 224, 0.30);
}

.gna-panel:hover .gna-panel__ghost {
  color: rgba(21, 96, 224, 0.13);
  transform: translateY(-4px);
}

.gna-panel:hover .gna-panel__title { color: $gna-blue-dk; }


/* =========================================================
   MOTION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gnaLift {
    from { opacity: 0; transform: translateY(26px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  @keyframes gnaFade {
    from { opacity: 0; transform: translateY(16px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  @keyframes gnaSweep {
    from { opacity: 0; transform: scaleY(0); }
    to   { opacity: 1; transform: scaleY(1); }
  }

  .gna-about .gna-eyebrow,
  .gna-about .gna-title {
    animation: gnaFade 0.72s cubic-bezier(0.2, 0.7, 0.3, 1) backwards;
  }

  .gna-about .gna-title { animation-delay: 0.09s; }

  .gna-about .gna-sub {
    transform-origin: top center;
    animation: gnaSweep 0.8s cubic-bezier(0.2, 0.7, 0.3, 1) 0.18s backwards;
  }

  .gna-panel {
    animation: gnaLift 0.82s cubic-bezier(0.2, 0.7, 0.3, 1) backwards;
  }

  .gna-panel--1 { animation-delay: 0.26s; }
  .gna-panel--2 { animation-delay: 0.38s; }
  .gna-panel--3 { animation-delay: 0.50s; }
  .gna-panel--4 { animation-delay: 0.62s; }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1024px) {

  .gna-about {
    margin-top: -40px;
    padding: 88px 22px 96px;
    border-radius: 40px 40px 0 0;
  }

  .gna-head {
    grid-template-columns: minmax(0, 1fr);
    gap: 26px;
  }

  .gna-about .gna-sub {
    padding-left: 22px;
    max-width: 620px;
  }

  .gna-grid {
    margin-top: 52px;
    gap: 18px;
  }

  .gna-panel--1,
  .gna-panel--2,
  .gna-panel--3,
  .gna-panel--4 { grid-column: span 12; }

  .gna-about .gna-panel__text { max-width: none; }
}

@media (max-width: 620px) {

  .gna-about {
    margin-top: -28px;
    padding: 64px 18px 72px;
    border-radius: 30px 30px 0 0;
  }

  .gna-panel { padding: 30px 26px 32px; }

  .gna-panel__ghost {
    font-size: 58px;
    top: 14px;
    right: 20px;
  }

  .gna-about .gna-panel__title { font-size: 21px; }
  .gna-about .gna-panel__text { font-size: 15.5px; }
  .gna-about .gna-sub { font-size: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  .gna-about * { transition: none; }
  .gna-panel:hover { transform: none; }
  .gna-panel:hover .gna-panel__icon { transform: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW LANDING · ABOUT
     Service Portal widget · Server script

     Copy is held here rather than in the template so every
     string passes through gs.getMessage and stays translatable.
     No table access, so no ACL considerations apply.
     ========================================================= */

  function opt(name, fallback) {
    var value = options[name];
    if (value === null || value === undefined || value === '') {
      return fallback;
    }
    return value.toString();
  }

  data.regionLabel = opt('region_label', gs.getMessage('About GateNow'));
  data.eyebrow     = opt('eyebrow', gs.getMessage('About GateNow'));
  data.title       = opt('title', gs.getMessage('One place for the whole grant, not just the form'));

  data.subhead = opt('subhead', gs.getMessage(
    'Funding applications rarely fall over on the idea. They fall over on ' +
    'version seven of the budget, a deadline nobody diarised, and a form ' +
    'asking for the same three numbers a fourth time. GateNow takes that ' +
    'part off your desk.'));

  data.steps = [
    {
      index : '01',
      icon  : 'fa-compass',
      kicker: gs.getMessage('Before you apply'),
      title : gs.getMessage('See what you can actually win'),
      text  : gs.getMessage(
        'GateNow checks your organisation against every open program and ' +
        'tells you what you qualify for up front. No more working through ' +
        'thirty pages of guidance to discover on page twenty nine that you ' +
        'were never eligible.')
    },
    {
      index : '02',
      icon  : 'fa-pencil',
      kicker: gs.getMessage('While you write'),
      title : gs.getMessage('Write the part only you can write'),
      text  : gs.getMessage(
        'Your registration number, latest accounts, board list and policies ' +
        'live in your profile and fill themselves in. What is left on the ' +
        'form is the bit that needs your judgement, not your filing cabinet.')
    },
    {
      index : '03',
      icon  : 'fa-eye',
      kicker: gs.getMessage('After you submit'),
      title : gs.getMessage('Never wonder who has it'),
      text  : gs.getMessage(
        'Every application carries its own state, its own owner and its own ' +
        'dates. When a reviewer needs something, it arrives as a task with a ' +
        'deadline on it, not a line halfway down a mail thread.')
    },
    {
      index : '04',
      icon  : 'fa-shield',
      kicker: gs.getMessage('Once you win'),
      title : gs.getMessage('The award is the middle, not the end'),
      text  : gs.getMessage(
        'Reports, claims and change requests hang off the same record as the ' +
        'bid that won it. Two years on, when the funder asks how the money ' +
        'was spent, the answer is already assembled.')
    }
  ];

})();
